-- Runs ONLY as --extra-flow in C01's temporary local database; the outer transaction rolls back.
reset role;
select ok((select relrowsecurity from pg_class where oid='public.incident_recoveries'::regclass),'recovery cases require RLS');
select ok(not has_table_privilege('authenticated','public.incident_recoveries','INSERT'),'authenticated users cannot forge cases');
select ok(not has_table_privilege('anon','public.incident_recoveries','SELECT'),'anonymous users cannot read cases');
set local role authenticated;
select pg_temp.actor('carrier');
insert into refs select 'incident',public.command_v2_carrier_workflow('__OPERATOR__','incidents.create',pg_temp.ctx(null,'__CARRIER__',pg_temp.id('execution'),null),gen_random_uuid(),
 jsonb_build_object('schemaVersion','2.0','kind','Carrier accident','severity','CRITICAL','occurredAt',now(),'location',null,'description','SYNTHETIC: truck one cannot fulfill its assignment','evidence',jsonb_build_array(pg_temp.ev())))->'record';
select pg_temp.actor('client');
insert into refs values('recovery-key',jsonb_build_object('id',gen_random_uuid()));
insert into refs select 'recovery-input',jsonb_build_object('schemaVersion','2.0','expectedIncidentVersion',1,'cause','CARRIER_ACCIDENT',
 'reservationIds',jsonb_build_array(pg_temp.id('reservation1')),'origin',jsonb_build_object('facilityId',pg_temp.id('facilityA')),
 'pickupWindow',jsonb_build_object('startsAt','2026-11-02T13:00:00Z','endsAt','2026-11-02T15:00:00Z'),
 'deliveryWindow',jsonb_build_object('startsAt','2026-11-02T19:00:00Z','endsAt','2026-11-02T23:00:00Z'),'timeZone','America/Lima','consent','AUTHORIZE_RECOVERY_SEARCH');
select throws_ok(format('select public.create_v2_incident_recovery(%L,%L,%L,%L,%L::jsonb)','__ORG__','__MEMBER__',pg_temp.id('incident'),gen_random_uuid(),(select value-'consent' from refs where name='recovery-input')),'PT400','VALIDATION_ERROR','native RPC requires explicit recovery consent');
select throws_ok(format('select public.create_v2_incident_recovery(%L,%L,%L,%L,%L::jsonb)','__ORG__','__MEMBER__',pg_temp.id('incident'),gen_random_uuid(),(select value||'{"expectedIncidentVersion":99}' from refs where name='recovery-input')),'PT409','STALE_DRAFT','stale incident version rejected');
select throws_ok(format('select public.create_v2_incident_recovery(%L,%L,%L,%L,%L::jsonb)','__ORG__','__MEMBER__',pg_temp.id('incident'),gen_random_uuid(),(select value||jsonb_build_object('reservationIds',jsonb_build_array(gen_random_uuid())) from refs where name='recovery-input')),'PT400','INVALID_RECOVERY_RESERVATION','unrelated reservations cannot be recovered');
insert into refs select 'recovery',public.create_v2_incident_recovery('__ORG__','__MEMBER__',pg_temp.id('incident'),pg_temp.id('recovery-key'),value) from refs where name='recovery-input';
select is(public.create_v2_incident_recovery('__ORG__','__MEMBER__',pg_temp.id('incident'),pg_temp.id('recovery-key'),(select value from refs where name='recovery-input')),(select value from refs where name='recovery'),'same idempotency key replays the same linked request');
select throws_ok(format('select public.create_v2_incident_recovery(%L,%L,%L,%L,%L::jsonb)','__ORG__','__MEMBER__',pg_temp.id('incident'),pg_temp.id('recovery-key'),(select value||'{"cause":"CARRIER_NONCOMPLIANCE"}' from refs where name='recovery-input')),'PT409','IDEMPOTENCY_CONFLICT','idempotency key cannot change its cause');
reset role;
select is((select count(*)::int from public.incident_recoveries),1,'exactly one recovery persisted');
select is((select cargo_weight_kg from public.freight_requests where id=(select (value->>'replacementRequestId')::uuid from refs where name='recovery')),6000::numeric,'replacement includes only failed truck cargo');
select is((select v2_snapshot#>>'{cargoSpecification,units,0,quantity}' from public.freight_requests where id=(select (value->>'replacementRequestId')::uuid from refs where name='recovery')),'1','indivisible crate is preserved');
select is((select v2_snapshot#>>'{planningPreferences,urgency}' from public.freight_requests where id=(select (value->>'replacementRequestId')::uuid from refs where name='recovery')),'URGENT','recovery uses urgent scheduling');
select is((select status from public.capacity_reservations where id=pg_temp.id('reservation1')),'CONFIRMED','failed commitment is not prematurely released');
select is((select status from public.capacity_reservations where id=pg_temp.id('reservation2')),'CONFIRMED','unaffected truck remains committed');
select is((select status from public.operational_incidents where id=pg_temp.id('incident')),'OPEN','incident stays open while searching');
set local role authenticated;
select pg_temp.actor('carrier');
select throws_ok(format('select public.command_v2_carrier_workflow(%L,%L,%L::jsonb,%L,%L::jsonb)','__OPERATOR__','incidents.update',pg_temp.ctx(null,'__CARRIER__',null,pg_temp.id('incident')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','expectedVersion',1,'action','RESOLVE','note','Premature resolution','evidence',pg_temp.ev())),'PT409','RECOVERY_REPLACEMENT_REQUIRED','Carrier cannot resolve an unconfirmed recovery');
select pg_temp.actor('client');
select is((public.read_v2_recovery_quote_context('__ORG__','__MEMBER__',(select (value->>'replacementRequestId')::uuid from refs where name='recovery'))->>'urgencySurcharge'),'0','recovery pricing explicitly waives urgency surcharge');
select is((public.read_v2_incident_recovery('__ORG__','__MEMBER__',pg_temp.id('request'))#>>'{cases,0,replacementRequestId}'),(select value->>'replacementRequestId' from refs where name='recovery'),'original order exposes its linked replacement');
reset role;

-- A second Carrier is created only inside the isolated test transaction. All capacity/tariffs below use native commands.
reset role;
insert into refs values('replacement-carrier',jsonb_build_object('id',gen_random_uuid())),('replacement-operator',jsonb_build_object('id',gen_random_uuid())),('replacement-user',jsonb_build_object('id',gen_random_uuid()));
insert into public.carriers select (jsonb_populate_record(null::public.carriers,to_jsonb(c)||jsonb_build_object('id',pg_temp.id('replacement-carrier'),'code','RECOVERY_TEST','name','[SIMULATED] Recovery test Carrier'))).* from public.carriers c where id='__CARRIER__';
insert into auth.users(id,aud,role) values(pg_temp.id('replacement-user'),'authenticated','authenticated');
insert into public.carrier_operators(id,carrier_id,auth_user_id,display_name,role,status,verified_at) values(pg_temp.id('replacement-operator'),pg_temp.id('replacement-carrier'),pg_temp.id('replacement-user'),'Synthetic recovery ADMIN','ADMIN','ACTIVE',now());
insert into private.v2_catalog_grants(auth_user_id,permission,carrier_id) values(pg_temp.id('replacement-user'),'CARRIER_EDITOR',pg_temp.id('replacement-carrier'));
create temporary table replacement_refs as select name,(value->>'id')::uuid id from refs where value?'id';
create function pg_temp.replacement_resolve(v jsonb) returns jsonb language plpgsql as $f$
declare answer jsonb;k text;x jsonb;begin
 if jsonb_typeof(v)='object' and v?'$ref' then return to_jsonb((select id from replacement_refs where name=v->>'$ref'));
 elsif jsonb_typeof(v)='object' then answer:='{}';for k,x in select * from jsonb_each(v) loop answer:=answer||jsonb_build_object(k,pg_temp.replacement_resolve(x));end loop;return answer;
 elsif jsonb_typeof(v)='array' then answer:='[]';for x in select value from jsonb_array_elements(v) loop answer:=answer||jsonb_build_array(pg_temp.replacement_resolve(x));end loop;return answer;
 elsif jsonb_typeof(v)='string' then return to_jsonb(replace(v#>>'{}','C01_SIM_V1','RECOVERY_TEST'));end if;return v;end;$f$;
