  elsif op->>'api'='workflow' then r:=public.command_v2_carrier_workflow(pg_temp.id('replacement-operator'),s->>'action',pg_temp.ctx(null,pg_temp.id('replacement-carrier')),gen_random_uuid(),v);ident:=(r#>>'{record,id}')::uuid;
  elsif op->>'api'='quotePolicy' then r:=public.configure_v2_quote_policy(pg_temp.id('replacement-carrier'),pg_temp.id('replacement-operator'),gen_random_uuid(),0,v);ident:=(r->>'id')::uuid;
  else raise exception 'UNSUPPORTED_TEST_OPERATION';end if;
