insert into refs select 'replacement-'||name,jsonb_build_object('id',id) from replacement_refs where name in('service','lane','truck1','calendar1');
set local role authenticated;
select pg_temp.actor('client');
select throws_ok(format('select public.request_v2_carrier_quote(%L,%L,%L,2,%L,%L,%L::jsonb)','__ORG__','__MEMBER__',(select value->>'replacementRequestId' from refs where name='recovery'),gen_random_uuid(),now()+interval '1 hour',(select value from refs where name='candidate')),'PT409','RECOVERY_FAILED_CARRIER_EXCLUDED','native quote adapter excludes the failed Carrier');
select ok(public.read_v2_recovery_blocked_calendars('__ORG__','__MEMBER__') ? pg_temp.id('calendar1')::text,'accident blocks reuse until availability is revalidated');
insert into refs select 'replacement-candidate',jsonb_build_object('serviceId',pg_temp.id('replacement-service'),'laneId',pg_temp.id('replacement-lane'),'calendarId',pg_temp.id('replacement-calendar1'),'assetId',pg_temp.id('replacement-truck1'),'poolId',null,
 'schedule',(select value->'schedule' from refs where name='candidate'));
insert into refs select 'replacement-quote',public.request_v2_carrier_quote('__ORG__','__MEMBER__',(select (value->>'replacementRequestId')::uuid from refs where name='recovery'),2,gen_random_uuid(),now()+interval '1 hour',value) from refs where name='replacement-candidate';
select is((select value->>'status' from refs where name='replacement-quote'),'OFFERED','different Carrier automatically issues an approved replacement tariff');
reset role;
select is((select data#>>'{breakdown,-1,amount,amount}' from public.v2_carrier_offers where id=(select (value->>'offerId')::uuid from refs where name='replacement-quote')),'0','native offer includes an explicit zero urgency/immediate-order surcharge');
select ok((select (data#>>'{price,amount}')::numeric>361.20 from public.v2_carrier_offers where id=(select (value->>'offerId')::uuid from refs where name='replacement-quote')),'normal replacement tariff is not capped at the original price');
select is((select data#>>'{commercialTerms,-1,code}' from public.v2_carrier_offers where id=(select (value->>'offerId')::uuid from refs where name='replacement-quote')),'INCIDENT_RECOVERY_NO_URGENCY_SURCHARGE','waiver remains attributable in the commercial terms');
set local role authenticated;
select pg_temp.actor('client');
insert into refs select 'replacement-decision',public.command_v2_workflow('__ORG__','__MEMBER__','decisions.create',pg_temp.ctx((select (value->>'replacementRequestId')::uuid from refs where name='recovery')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','planId',value->>'planId','selectedOfferIds',jsonb_build_array(value->>'offerId'),'consideredOfferIds',jsonb_build_array(value->>'offerId'),'policyId',null,'rationale','Client explicitly approves normal replacement tariff, urgency surcharge zero','evidence',jsonb_build_array(pg_temp.ev())))->'record' from refs where name='replacement-quote';
insert into refs select 'replacement-booking',public.command_v2_workflow('__ORG__','__MEMBER__','bookings.create',pg_temp.ctx((select (value->>'replacementRequestId')::uuid from refs where name='recovery')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','decisionId',pg_temp.id('replacement-decision'),'offerId',value->>'offerId','authorization','AUTHORIZE','evidence',pg_temp.ev()))->'record' from refs where name='replacement-quote';
insert into refs select 'replacement-execution',public.command_v2_workflow('__ORG__','__MEMBER__','executions.create',pg_temp.ctx((select (value->>'replacementRequestId')::uuid from refs where name='recovery')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','bookingId',pg_temp.id('replacement-booking'),'serviceId',pg_temp.id('replacement-service')))->'record';
insert into refs select 'replacement-plan',public.read_v2_workflow('__ORG__','__MEMBER__','plans',pg_temp.ctx(null,null,null,(select (value->>'planId')::uuid from refs where name='replacement-quote')),100,0)->0;
insert into refs select 'replacement-hold',public.command_v2_workflow('__ORG__','__MEMBER__','holds.create',pg_temp.ctx((select (value->>'replacementRequestId')::uuid from refs where name='recovery')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','bookingId',pg_temp.id('replacement-booking'),'assignmentId',value#>>'{data,legAssignments,0,id}','planResourceId',value#>>'{data,legAssignments,0,resources,0,resourceId}','expiresAt',now()+interval '20 minutes','consolidationId',null,'evidence',value#>'{data,legAssignments,0,resources,0,resource,verificationSource,source}'))->'record' from refs where name='replacement-plan';
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id('replacement-user'),'role','authenticated')::text,true);
select public.command_v2_carrier_workflow(pg_temp.id('replacement-operator'),'holds.confirm',pg_temp.ctx(null,pg_temp.id('replacement-carrier'),null,pg_temp.id('replacement-hold')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','expectedVersion',1,'note','Synthetic recovery capacity confirmation','evidence',pg_temp.ev()));
reset role;
select is((select status from public.operational_incidents where id=pg_temp.id('incident')),'OPEN','capacity confirmation alone does not resolve incident');
set local role authenticated;
select public.command_v2_carrier_workflow(pg_temp.id('replacement-operator'),'bookings.confirm',pg_temp.ctx(null,pg_temp.id('replacement-carrier'),null,pg_temp.id('replacement-booking')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','expectedVersion',1,'note','Synthetic replacement Carrier confirms','evidence',pg_temp.ev(),'carrierReference','RECOVERY_TEST','confirmation','CONFIRMED'));
reset role;
select is((select status from public.incident_recoveries where id=pg_temp.id('recovery')),'REPLACED','recovery finalizes only on replacement Carrier confirmation');
select is((select status from public.operational_incidents where id=pg_temp.id('incident')),'RESOLVED','replacement resolves the incident atomically');
select is((select status from public.capacity_reservations where id=pg_temp.id('reservation1')),'RELEASED','only failed reservation released');
select is((select status from public.capacity_reservations where id=pg_temp.id('reservation2')),'CONFIRMED','unaffected reservation retained');
select is((select count(*)::int from public.vehicle_assignments where execution_id=pg_temp.id('execution') and status='CONFIRMED'),1,'only failed truck assignment released');
select is((select status from public.v2_bookings where id=pg_temp.id('booking')),'CONFIRMED','partial recovery retains the original booking');
select is((select status from public.transport_executions where id=pg_temp.id('replacement-execution')),'PLANNED','replacement does not invent a transport start');
select is((select count(*)::int from public.driver_assignments where execution_id=pg_temp.id('execution') and status='CONFIRMED'),2,'no unsupported driver-to-truck pairing is invented');

-- Controlled simulated running-trip state; no real transport is started.
reset role;
update public.transport_executions set status='IN_PROGRESS',actual_started_at=now(),version=version+1 where id=pg_temp.id('execution');
set local role authenticated;
select pg_temp.actor('carrier');
insert into refs select 'incident-second',public.command_v2_carrier_workflow('__OPERATOR__','incidents.create',pg_temp.ctx(null,'__CARRIER__',pg_temp.id('execution'),null),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','kind','Noncompliance','severity','CRITICAL','occurredAt',now(),'location',null,'description','SYNTHETIC: remaining truck cannot fulfill','evidence',jsonb_build_array(pg_temp.ev())))->'record';
select pg_temp.actor('client');
insert into refs select 'recovery-second-input',value||jsonb_build_object('reservationIds',jsonb_build_array(pg_temp.id('reservation2')),'cause','CARRIER_NONCOMPLIANCE') from refs where name='recovery-input';
select throws_ok(format('select public.create_v2_incident_recovery(%L,%L,%L,%L,%L::jsonb)','__ORG__','__MEMBER__',pg_temp.id('incident-second'),gen_random_uuid(),(select value from refs where name='recovery-second-input')),'PT400','REMAINING_CARGO_CONFIRMATION_REQUIRED','running trip cannot assume original cargo is still pending');
insert into refs select 'recovery-second',public.create_v2_incident_recovery('__ORG__','__MEMBER__',pg_temp.id('incident-second'),gen_random_uuid(),value||jsonb_build_object('confirmRemainingCargo',true,'remainingAllocations',jsonb_build_array(jsonb_build_object('unitIndex',0,'quantity',1)))) from refs where name='recovery-second-input';
reset role;
select is((select cargo_weight_kg from public.freight_requests where id=(select (value->>'replacementRequestId')::uuid from refs where name='recovery-second')),6000::numeric,'running-trip recovery uses explicitly confirmed remaining packages');
insert into refs select 'replacement-'||name,jsonb_build_object('id',id) from replacement_refs where name in('truck2','calendar2');
set local role authenticated;select pg_temp.actor('client');
insert into refs select 'second-candidate',jsonb_build_object('serviceId',pg_temp.id('replacement-service'),'laneId',pg_temp.id('replacement-lane'),'calendarId',pg_temp.id('replacement-calendar2'),'assetId',pg_temp.id('replacement-truck2'),'poolId',null,
 'schedule',(select value->'schedule' from refs where name='candidate'));
insert into refs select 'second-quote',public.request_v2_carrier_quote('__ORG__','__MEMBER__',(select (value->>'replacementRequestId')::uuid from refs where name='recovery-second'),2,gen_random_uuid(),now()+interval '1 hour',value) from refs where name='second-candidate';
select is((select value->>'status' from refs where name='second-quote'),'OFFERED','different Carrier automatically issues an approved replacement tariff');
reset role;
select is((select data#>>'{breakdown,-1,amount,amount}' from public.v2_carrier_offers where id=(select (value->>'offerId')::uuid from refs where name='second-quote')),'0','native offer includes an explicit zero urgency/immediate-order surcharge');
select ok((select (data#>>'{price,amount}')::numeric>361.20 from public.v2_carrier_offers where id=(select (value->>'offerId')::uuid from refs where name='second-quote')),'normal replacement tariff is not capped at the original price');
select is((select data#>>'{commercialTerms,-1,code}' from public.v2_carrier_offers where id=(select (value->>'offerId')::uuid from refs where name='second-quote')),'INCIDENT_RECOVERY_NO_URGENCY_SURCHARGE','waiver remains attributable in the commercial terms');
set local role authenticated;
select pg_temp.actor('client');
insert into refs select 'second-decision',public.command_v2_workflow('__ORG__','__MEMBER__','decisions.create',pg_temp.ctx((select (value->>'replacementRequestId')::uuid from refs where name='recovery-second')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','planId',value->>'planId','selectedOfferIds',jsonb_build_array(value->>'offerId'),'consideredOfferIds',jsonb_build_array(value->>'offerId'),'policyId',null,'rationale','Client explicitly approves normal replacement tariff, urgency surcharge zero','evidence',jsonb_build_array(pg_temp.ev())))->'record' from refs where name='second-quote';
insert into refs select 'second-booking',public.command_v2_workflow('__ORG__','__MEMBER__','bookings.create',pg_temp.ctx((select (value->>'replacementRequestId')::uuid from refs where name='recovery-second')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','decisionId',pg_temp.id('second-decision'),'offerId',value->>'offerId','authorization','AUTHORIZE','evidence',pg_temp.ev()))->'record' from refs where name='second-quote';
insert into refs select 'second-execution',public.command_v2_workflow('__ORG__','__MEMBER__','executions.create',pg_temp.ctx((select (value->>'replacementRequestId')::uuid from refs where name='recovery-second')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','bookingId',pg_temp.id('second-booking'),'serviceId',pg_temp.id('replacement-service')))->'record';
insert into refs select 'second-plan',public.read_v2_workflow('__ORG__','__MEMBER__','plans',pg_temp.ctx(null,null,null,(select (value->>'planId')::uuid from refs where name='second-quote')),100,0)->0;
insert into refs select 'second-hold',public.command_v2_workflow('__ORG__','__MEMBER__','holds.create',pg_temp.ctx((select (value->>'replacementRequestId')::uuid from refs where name='recovery-second')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','bookingId',pg_temp.id('second-booking'),'assignmentId',value#>>'{data,legAssignments,0,id}','planResourceId',value#>>'{data,legAssignments,0,resources,0,resourceId}','expiresAt',now()+interval '20 minutes','consolidationId',null,'evidence',value#>'{data,legAssignments,0,resources,0,resource,verificationSource,source}'))->'record' from refs where name='second-plan';
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id('replacement-user'),'role','authenticated')::text,true);
select public.command_v2_carrier_workflow(pg_temp.id('replacement-operator'),'holds.confirm',pg_temp.ctx(null,pg_temp.id('replacement-carrier'),null,pg_temp.id('second-hold')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','expectedVersion',1,'note','Synthetic recovery capacity confirmation','evidence',pg_temp.ev()));
reset role;
select is((select status from public.operational_incidents where id=pg_temp.id('incident-second')),'OPEN','capacity confirmation alone does not resolve incident');
set local role authenticated;
select public.command_v2_carrier_workflow(pg_temp.id('replacement-operator'),'bookings.confirm',pg_temp.ctx(null,pg_temp.id('replacement-carrier'),null,pg_temp.id('second-booking')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','expectedVersion',1,'note','Synthetic replacement Carrier confirms','evidence',pg_temp.ev(),'carrierReference','RECOVERY_TEST','confirmation','CONFIRMED'));
reset role;

reset role;
select is((select status from public.capacity_reservations where id=pg_temp.id('reservation2')),'RELEASED','last failed reservation released on replacement confirmation');
select is((select status from public.v2_bookings where id=pg_temp.id('booking')),'CANCELLED','fully replaced original booking is cancelled with history retained');
select is((select status from public.transport_executions where id=pg_temp.id('execution')),'CANCELLED','fully replaced original execution is cancelled');
select is((select count(*)::int from public.driver_assignments where execution_id=pg_temp.id('execution') and status='CONFIRMED'),0,'original drivers released only when entire execution is replaced');
select is((select count(*)::int from public.incident_recoveries where status='REPLACED'),2,'both partial recoveries remain auditable');
